let navigationItems=OrbitNavigation.defaults.map(item=>({...item,iconData:'',custom:false}));
let navigationDraft=null,navDrag=null,navClickBlockedUntil=0;
function navigationIcon(item){if(item.iconData)return '<img src="'+escapeHtml(item.iconData)+'" alt="" draggable="false">';if(item.iconSrc)return '<img src="'+escapeHtml(item.iconSrc)+'" alt="" draggable="false">';if(item.iconKey)return icon(item.iconKey);return '<span class="nav-initial-icon" aria-hidden="true">'+escapeHtml(OrbitNavigation.initial(displayNavigationName(item)))+'</span>';}
function displayNavigationName(item){const original=OrbitNavigation.defaults.find(n=>n.id===item.id);return OrbitI18n.text(item.name,prefs.language);}
function navigationItem(id){return navigationItems.find(item=>item.id===id);}
function renderWorkspaceNavigation(){if(navDrag?.active)return;$('#main-nav').innerHTML=navigationItems.map(item=>'<a class="nav-item '+(item.shortcut?'shortcut-link ':'')+(item.id==='chatgpt'?'chatgpt-nav ':'')+(item.custom?'custom-link ':'')+(state.page===item.id?'active':'')+'" data-nav-id="'+escapeHtml(item.id)+'" href="#'+escapeHtml(item.id)+'" '+(state.page===item.id?'aria-current="page"':'')+'>'+navigationIcon(item)+'<span class="nav-label">'+escapeHtml(displayNavigationName(item))+'</span></a>').join('');}
async function loadNavigation(){if(window.orbitDesktop){const result=await window.orbitDesktop.getNavigation();if(result.ok){navigationItems=result.items;render();}else toast(result.error);}else{const saved=readStorage('navigation',null);if(Array.isArray(saved)){navigationItems=readStorage('navigationVersion',1)===2?saved:OrbitNavigation.restoreRequired(saved);try{localStorage.setItem('orbit:navigation',JSON.stringify(navigationItems));localStorage.setItem('orbit:navigationVersion','2');}catch{}render();}}}
function acceptNavigation(result){if(!result?.ok){toast(result?.error||'导航保存失败。');return false;}navigationItems=result.items;if(!window.orbitDesktop){try{localStorage.setItem('orbit:navigation',JSON.stringify(navigationItems));localStorage.setItem('orbit:navigationVersion','2');}catch{}}render();return true;}
function updateNavigationPreview(){if(!navigationDraft)return;const name=$('#nav-name')?.value||'';const item={...navigationDraft,name};$('#navigation-icon-preview').innerHTML=navigationIcon(item);}
function navigationModal(id){const item=navigationItem(id);navigationDraft=item?{...item}:{name:'',url:'',iconData:'',custom:true};openModal(item?'编辑导航页':'新增导航页','<form data-form="navigation"><label for="nav-name">名称</label><input id="nav-name" name="name" value="'+escapeHtml(navigationDraft.name)+'" maxlength="40" required autocomplete="off">'+(navigationDraft.internal?'':'<label for="nav-url">网页地址</label><input id="nav-url" name="url" type="url" value="'+escapeHtml(navigationDraft.url||'')+'" placeholder="https://" required>')+'<label>图标</label><div class="navigation-icon-picker"><span id="navigation-icon-preview"></span><button type="button" class="secondary-btn" data-action="navigation-icon">从桌面选择</button><button type="button" class="text-link" data-action="navigation-icon-default">默认图标</button></div><div class="modal-actions"><button type="button" class="secondary-btn" data-action="close-modal">取消</button><button type="submit" class="primary-btn">保存</button></div></form>');updateNavigationPreview();$('#nav-name').focus();}
async function pickNavigationIcon(){if(!window.orbitDesktop)return;const result=await window.orbitDesktop.pickNavigationIcon();if(!result.ok){toast(result.error);return;}if(result.canceled||!navigationDraft)return;navigationDraft.iconData=result.iconData;updateNavigationPreview();}
async function saveNavigationForm(form,fields){if(!navigationDraft)return;const input={...(navigationDraft.id?{id:navigationDraft.id}:{}),name:String(fields.get('name')||'').trim(),url:String(fields.get('url')||'').trim(),iconData:navigationDraft.iconData||''};if(!navigationDraft.internal){try{const url=new URL(input.url);if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error();}catch{toast('请输入完整的 http:// 或 https:// 网页地址。');return;}}const result=window.orbitDesktop?await window.orbitDesktop.saveNavigation(input):{ok:true,items:navigationDraft.id?navigationItems.map(item=>item.id===input.id?{...item,...input}:item):[...navigationItems,{...input,id:'nav-'+crypto.randomUUID(),custom:true}]};if(result.ok){closeModal();navigationDraft=null;acceptNavigation(result);toast('导航已保存。');}else toast(result.error);}
async function deleteNavigation(id){const old=navigationItem(id);if(!old)return;const result=window.orbitDesktop?await window.orbitDesktop.deleteNavigation(id):{ok:true,items:navigationItems.filter(item=>item.id!==id)};if(!result.ok){toast(result.error);return;}if(state.page===id){state.page='overview';history.replaceState(null,'','#overview');}acceptNavigation(result);toast('导航已删除。');}
async function commitNavigationOrder(ids){const result=window.orbitDesktop?await window.orbitDesktop.reorderNavigation(ids):{ok:true,items:ids.map(id=>navigationItem(id))};acceptNavigation(result);}
function finishNavigationDrag(commit){const drag=navDrag;if(!drag)return;clearTimeout(drag.timer);clearInterval(drag.scrollTimer);navDrag=null;document.body.classList.remove('navigation-dragging');drag.row.classList.remove('is-dragging');if(drag.row.hasPointerCapture?.(drag.pointerId))drag.row.releasePointerCapture(drag.pointerId);if(drag.active){navClickBlockedUntil=performance.now()+500;const ids=[...document.querySelectorAll('#main-nav [data-nav-id]')].map(row=>row.dataset.navId);if(commit&&ids.join('|')!==navigationItems.map(item=>item.id).join('|'))commitNavigationOrder(ids);else renderWorkspaceNavigation();}}
document.addEventListener('pointerdown',event=>{const row=event.target.closest('#main-nav [data-nav-id]');if(!row||event.button!==0||$('#modal').open)return;finishNavigationDrag(false);const drag={row,pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,y:event.clientY,active:false};navDrag=drag;drag.timer=setTimeout(()=>{if(navDrag!==drag)return;drag.active=true;drag.row.classList.add('is-dragging');document.body.classList.add('navigation-dragging');try{drag.row.setPointerCapture(event.pointerId);}catch{}drag.scrollTimer=setInterval(()=>{const scroller=$('.sidebar-navigation'),rect=scroller.getBoundingClientRect();if(drag.y<rect.top+34)scroller.scrollTop-=12;else if(drag.y>rect.bottom-34)scroller.scrollTop+=12;},40);},400);});
document.addEventListener('pointermove',event=>{const drag=navDrag;if(!drag||drag.pointerId!==event.pointerId)return;drag.y=event.clientY;if(!drag.active){if(Math.hypot(event.clientX-drag.startX,event.clientY-drag.startY)>7)finishNavigationDrag(false);return;}event.preventDefault();const rows=[...document.querySelectorAll('#main-nav [data-nav-id]')].filter(row=>row!==drag.row);const before=rows.find(row=>{const rect=row.getBoundingClientRect();return event.clientY<rect.top+rect.height/2;});if(before)$('#main-nav').insertBefore(drag.row,before);else $('#main-nav').append(drag.row);},{passive:false});
document.addEventListener('pointerup',event=>{if(navDrag?.pointerId===event.pointerId)finishNavigationDrag(true);});
document.addEventListener('pointercancel',()=>finishNavigationDrag(false));
window.addEventListener('blur',()=>finishNavigationDrag(false));
document.addEventListener('click',event=>{if(event.target.closest('[data-nav-id]')&&performance.now()<navClickBlockedUntil){event.preventDefault();event.stopImmediatePropagation();}},true);
document.addEventListener('dragstart',event=>{if(event.target.closest('[data-nav-id]'))event.preventDefault();});
document.addEventListener('contextmenu',event=>{const row=event.target.closest('[data-nav-id]');if(!row)return;event.preventDefault();finishNavigationDrag(false);if(window.orbitDesktop)window.orbitDesktop.showNavigationMenu(row.dataset.navId);else navigationModal(row.dataset.navId);});
document.addEventListener('keydown',event=>{const row=event.target.closest('[data-nav-id]');if(!row||!event.altKey||!['ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const ids=navigationItems.map(item=>item.id),index=ids.indexOf(row.dataset.navId),target=index+(event.key==='ArrowUp'?-1:1);if(target<0||target>=ids.length)return;[ids[index],ids[target]]=[ids[target],ids[index]];commitNavigationOrder(ids).then(()=>$('#main-nav [data-nav-id="'+row.dataset.navId+'"]').focus());});
document.addEventListener('input',event=>{if(event.target.id==='nav-name')updateNavigationPreview();});
window.orbitDesktop?.onNavigationAction(action=>{if(action.action==='edit')navigationModal(action.id);else if(action.action==='delete')deleteNavigation(action.id);});
